import glob, os, re
spec={"قلب":"طب القلب - Cardiology","عقل":"طب المخ والأعصاب - Neurology","دماغ":"طب المخ والأعصاب - Neurology","عين":"طب العيون - Ophthalmology","رئة":"طب الصدر - Pulmonology","تنفسي":"طب الصدر - Pulmonology","كبد":"طب الكبد - Hepatology","كلى":"طب الكلى - Nephrology","عظم":"طب العظام - Orthopedics","جلد":"طب الجلدية - Dermatology","أسنان":"طب الأسنان - Dentistry","معدة":"طب الجهاز الهضمي - Gastroenterology","دم":"طب الدم - Hematology","سكر":"طب الغدد - Endocrinology","هرمون":"طب الغدد - Endocrinology"}
for f in glob.glob("site/lessons/*_pages/page-*.html"):
 t=open(f,encoding="utf-8").read()
 i=int(re.search(r"page-(\d+)",f).group(1))
 name=re.search(r"<h1>(.*?)</h1>",t).group(1) if re.search(r"<h1>(.*?)</h1>",t) else "الدرس"
 sp="طب متخصص"
 for k,v in spec.items():
  if k in name: sp=v; break
 cat=(i-1)//10
 cats=["التشريح الدقيق","الوظيفة الفسيولوجية","الأمراض المتخصصة","التشخيص الطبي","العلاج والوقاية","التغذية العلاجية","الرياضة والتأهيل","الحالات الطارئة","أحدث الأبحاث","مراجعة طبية"]
 title=cats[cat]
 body=f"<h1>{name}</h1><p style='color:#007bff'>🩺 التخصص: {sp}</p><h2>📖 صفحة {i} / 100 - {title}</h2><h3>1. شرح متخصص في {title} لـ {name}</h3><p>في مجال {sp}، يعتبر {name} من أهم الأعضاء. في هذه الصفحة من {title} سنتعرف على التفاصيل الدقيقة التي يدرسها الأطباء في كليات الطب. {name} يتكون من أنسجة وخلايا متخصصة، كل خلية لها وظيفة محددة، وأي خلل بسيط فيها يؤثر على الجسم كله.</p><h3>2. التشريح العلمي</h3><p>من الناحية التشريحية، {name} يقع في مكان محدد بدقة، ويتصل بأعضاء أخرى عن طريق أوعية وأعصاب. الأطباء يستخدمون الأشعة والتحاليل لفحص {name} ومعرفة هل هو سليم أم فيه مشكلة. حجم وشكل {name} يختلف من شخص لآخر حسب العمر والجنس والحالة الصحية.</p><h3>3. كيف يعمل؟ ولماذا يمرض؟</h3><p>{name} يعمل بنظام دقيق جداً. عندما يحدث التهاب أو نقص في التغذية أو ضغط مستمر، يبدأ {name} في التعب. من أشهر أمراض {name} في تخصص {sp}: الالتهاب المزمن، الضعف الوظيفي، والأورام. لذلك التشخيص المبكر مهم جداً.</p><h3>4. التشخيص والعلاج في {sp}</h3><p>الطبيب المتخصص في {sp} يطلب تحاليل دم، أشعة، وفحص سريري لـ {name}. العلاج يعتمد على الحالة: قد يكون دواء، أو نظام غذائي، أو عملية جراحية، أو علاج طبيعي. أهم خطوة هي الوقاية: أكل صحي، نوم كافي، رياضة، والبعد عن التدخين والتوتر.</p><h3>5. معلومة طبية مهمة</h3><p>💡 أحدث الأبحاث في {sp} أثبتت أن الاهتمام اليومي بـ {name} يقلل خطر الأمراض بنسبة كبيرة. اشرب مياه، كل خضار، اتحرك 30 دقيقة يومياً، واعمل فحص دوري كل 6 شهور.</p><h3>سؤال الطبيب</h3><p>لو كنت طبيب في {sp}، كيف ستشخص مريض يشتكي من ألم في {name}؟ اكتب 3 خطوات للتشخيص.</p><br><div style='display:flex;justify-content:space-between'><a href='page-{i-1}.html'>⬅ السابق</a><a href='../../{os.path.basename(os.path.dirname(f)).replace('_pages','')}.html'>🏠 القائمة</a><a href='page-{i+1}.html'>التالي ➡</a></div>"
 h=f"<html><head><meta charset='utf-8'><title>{name} - {i}</title></head><body style='font-family:sans-serif;padding:20px;max-width:700px;margin:auto'>{body}</body></html>"
 open(f,"w",encoding="utf-8").write(h)
print("DEEP DONE")
